# Find the actual test input grid data
import json
with open('/home/USER/runs/paper/qwen-h0c1-card/frozen/held-out-reference-3/play/users/u079/system/state/session-artifacts/01a188fc-ae7c-76fd-a2d9-3028130f9795/semantic-edges.jsonl') as f:
    lines = f.readlines()

# Search for actual grid rows (should contain numbers 0-9)
grid_rows_found = []
for i, line in enumerate(lines):
    entry = json.loads(line)
    # Look for rows with pattern like "1 1 4 X X..." 
    for key, val in entry.items():
        if isinstance(val, str):
            s = val.lower()
            if 'row' in s and (' ' in val and any(c.isdigit() for c in val)):
                if len(val.split()) > 5 and all(v.replace(' ', '').isdigit() or v == '' for v in val.split()):
                    grid_rows_found.append((i, val[:150]))

            # Also look for array-like format
            if '[' in val and ']' in val and ',' in val:
                try:
                    arr = json.loads(val)
                    if isinstance(arr, list) and len(arr) > 10:
                        if all(isinstance(x, int) or x is None for x in arr):
                            grid_rows_found.append((i, str(arr)[:200]))
                except:
                    pass

print(f"Found {len(grid_rows_found)} potential grid entries")
if grid_rows_found:
    print("\nSample entries:")
    for idx, row_str in grid_rows_found[:3]:
        print(f"[{idx}] {row_str}")

