lines = [l.split() for l in test_input_str.strip().split('\n')]

def find_zero_start(row):
    return next(i for i, v in enumerate(row) if v == '0')

print("All row structures:")
for r in range(28):
    zero_start = find_zero_start(lines[r]) if any(v=='0' for v in lines[r]) else 28

    # Get non-zero prefix (cols 3-10) for rows 3-8
    if 3 <= r < 9:
        left_part = ''.join(lines[r][3:zero_start])[:20]
        print(f"Row {r}: zeros at {zero_start}, left='{left_part}'")

    # For rows 9-17 with zeros on left
    elif 9 <= r <= 17:
        # These have zeros starting from cols 1 or 0
        first_nonzero_left = None
        for c in range(zero_start - 1, -1, -1):
            if lines[r][c] != '0':
                first_nonzero_left = c
                break
        right_first_nonzero = None
        for c in range(4, 28):
